package main

import (
	"encoding/json"
	"net/http"
	"testing"
)

// Temporary verification for the distant-timestamp batch fix.
func TestTmpDistantTimestampsBatch(t *testing.T) {
	p := startServer(t, t.TempDir())

	body := `{"samples":[
		{"id":"a","service":"gateway","name":"requests","at":"2000-01-01T00:00:00Z","value":100,"labels":{"env":"prod"}},
		{"id":"b","service":"gateway","name":"requests","at":"2584-07-20T23:34:33.709551616Z","value":130,"labels":{"env":"prod"}}
	]}`
	status, raw := httpDo(t, http.MethodPost, "http://"+p.addr+"/metrics", body)
	if status != http.StatusOK {
		t.Fatalf("batch status %d: %s", status, raw)
	}
	var counts map[string]int
	if err := json.Unmarshal(raw, &counts); err != nil {
		t.Fatal(err)
	}
	if counts["created"] != 2 || counts["replayed"] != 0 {
		t.Fatalf("counts=%v", counts)
	}

	// Reversed batch order on a fresh server must behave identically.
	p2 := startServer(t, t.TempDir())
	bodyRev := `{"samples":[
		{"id":"b","service":"gateway","name":"requests","at":"2584-07-20T23:34:33.709551616Z","value":130,"labels":{"env":"prod"}},
		{"id":"a","service":"gateway","name":"requests","at":"2000-01-01T00:00:00Z","value":100,"labels":{"env":"prod"}}
	]}`
	status, raw = httpDo(t, http.MethodPost, "http://"+p2.addr+"/metrics", bodyRev)
	if status != http.StatusOK {
		t.Fatalf("reversed batch status %d: %s", status, raw)
	}

	// One-minute windows starting at each sample, step one minute.
	_, agg1 := metricAggregate(t, p, "?name=requests&since=2000-01-01T00:00:00Z&until=2000-01-01T00:01:00Z&step=60")
	seg1 := agg1[0]["segments"].([]any)[0].(map[string]any)
	if seg1["count"].(float64) != 1 || seg1["delta"].(float64) != 0 {
		t.Fatalf("early window: %v", seg1)
	}
	_, agg2 := metricAggregate(t, p, "?name=requests&since=2584-07-20T23:34:33.709551616Z&until=2584-07-20T23:35:33.709551616Z&step=60")
	seg2 := agg2[0]["segments"].([]any)[0].(map[string]any)
	if seg2["count"].(float64) != 1 || seg2["delta"].(float64) != 30 {
		t.Fatalf("late window: %v", seg2)
	}

	// Same absolute instant with a different offset must still conflict (409),
	// against a stored sample and within one batch, leaving nothing behind.
	conflictStored := `{"samples":[
		{"id":"c","service":"gateway","name":"requests","at":"2000-01-01T02:00:00+02:00","value":100,"labels":{"env":"prod"}}
	]}`
	status, raw = httpDo(t, http.MethodPost, "http://"+p.addr+"/metrics", conflictStored)
	if status != http.StatusConflict {
		t.Fatalf("offset-alias vs stored: status %d: %s", status, raw)
	}
	var errBody map[string]any
	if err := json.Unmarshal(raw, &errBody); err != nil || errBody["error"] == "" {
		t.Fatalf("conflict body must carry non-empty error: %s", raw)
	}

	conflictBatch := `{"samples":[
		{"id":"d","service":"gateway","name":"requests","at":"2001-06-01T00:00:00Z","value":1,"labels":{"env":"prod"}},
		{"id":"e","service":"gateway","name":"requests","at":"2001-06-01T05:00:00+05:00","value":2,"labels":{"env":"prod"}}
	]}`
	status, _ = httpDo(t, http.MethodPost, "http://"+p.addr+"/metrics", conflictBatch)
	if status != http.StatusConflict {
		t.Fatalf("offset-alias within batch: status %d", status)
	}
	_, agg3 := metricAggregate(t, p, "?name=requests&since=2001-06-01T00:00:00Z&until=2001-06-01T00:01:00Z&step=60")
	if len(agg3) != 1 || agg3[0]["segments"].([]any)[0].(map[string]any)["count"].(float64) != 0 {
		t.Fatalf("rejected batch must leave nothing: %v", agg3)
	}

	// One nanosecond apart must be accepted as distinct points.
	oneNs := `{"samples":[
		{"id":"f","service":"gateway","name":"requests","at":"2584-07-20T23:34:33.709551617Z","value":131,"labels":{"env":"prod"}}
	]}`
	status, raw = httpDo(t, http.MethodPost, "http://"+p.addr+"/metrics", oneNs)
	if status != http.StatusOK {
		t.Fatalf("1ns-apart sample: status %d: %s", status, raw)
	}

	// Same instant but different labels: different series, no conflict.
	otherLabels := `{"samples":[
		{"id":"g","service":"gateway","name":"requests","at":"2000-01-01T00:00:00Z","value":7,"labels":{"env":"dev"}}
	]}`
	status, raw = httpDo(t, http.MethodPost, "http://"+p.addr+"/metrics", otherLabels)
	if status != http.StatusOK {
		t.Fatalf("different-labels same instant: status %d: %s", status, raw)
	}
}

