	otherLabels := `{"samples":[
		{"id":"g","service":"gateway","name":"requests","at":"2000-01-01T00:00:00Z","value":7,"labels":{"env":"dev"}}
	]}`
	status, raw = httpDo(t, http.MethodPost, "http://"+p.addr+"/metrics", otherLabels)
	if status != http.StatusOK {
		t.Fatalf("different-labels same instant: status %d: %s", status, raw)
	}
}

